import os

components = {
    'src/components/ui/Breadcrumbs.tsx': '''import Link from "next/link"\\nimport { ChevronRight } from "lucide-react"\\n\\ninterface BreadcrumbItem {\\n  label: string\\n  href: string\\n}\\n\\nexport function Breadcrumbs({ items }: { items: BreadcrumbItem[] }) {\\n  return (\\n    <nav aria-label="Breadcrumb" className="py-4">\\n      <ol className="flex items-center space-x-2 text-sm text-brand-charcoal/60">\\n        <li>\\n          <Link href="/" className="hover:text-brand-navy transition-colors">Home</Link>\\n        </li>\\n        {items.map((item, index) => (\\n          <li key={index} className="flex items-center space-x-2">\\n            <ChevronRight className="w-4 h-4" />\\n            {index === items.length - 1 ? (\\n              <span className="text-brand-navy font-medium" aria-current="page">{item.label}</span>\\n            ) : (\\n              <Link href={item.href} className="hover:text-brand-navy transition-colors">{item.label}</Link>\\n            )}\\n          </li>\\n        ))}\\n      </ol>\\n    </nav>\\n  )\\n}\\n''',

    'src/components/ui/FAQ.tsx': '''"use client"\\nimport * as React from "react"\\nimport { cn } from "@/lib/utils"\\nimport { ChevronDown } from "lucide-react"\\n\\nexport function FAQ({ items }: { items: { question: string, answer: string }[] }) {\\n  const [openIndex, setOpenIndex] = React.useState<number | null>(null)\\n  \\n  return (\\n    <div className="space-y-4">\\n      {items.map((item, i) => (\\n        <div key={i} className="border border-brand-navy/10 rounded-lg overflow-hidden">\\n          <button \\n            className="w-full px-6 py-4 flex items-center justify-between bg-white text-left focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy"\\n            onClick={() => setOpenIndex(openIndex === i ? null : i)}\\n            aria-expanded={openIndex === i}\\n          >\\n            <span className="font-serif font-bold text-brand-navy text-lg">{item.question}</span>\\n            <ChevronDown className={cn("w-5 h-5 text-brand-gold transition-transform", openIndex === i && "rotate-180")} />\\n          </button>\\n          <div className={cn("px-6 overflow-hidden transition-all duration-300", openIndex === i ? "max-h-96 py-4" : "max-h-0 py-0")}>\\n            <p className="text-brand-charcoal/80 font-sans">{item.answer}</p>\\n          </div>\\n        </div>\\n      ))}\\n    </div>\\n  )\\n}\\n''',

    'src/components/ui/PageHero.tsx': '''import Image from "next/image"\\n\\ninterface PageHeroProps {\\n  title: string\\n  description?: string\\n  imageSrc: string\\n}\\n\\nexport function PageHero({ title, description, imageSrc }: PageHeroProps) {\\n  return (\\n    <section className="relative h-[50vh] min-h-[400px] flex items-center bg-brand-navy overflow-hidden">\\n      <div className="absolute inset-0 z-0 opacity-40">\\n        <div className="w-full h-full bg-gradient-to-t from-brand-navy via-brand-navy/60 to-transparent absolute z-10" />\\n        <Image \\n          src={imageSrc} \\n          alt={title} \\n          fill \\n          className="object-cover grayscale mix-blend-overlay"\\n          priority\\n        />\\n      </div>\\n      <div className="container mx-auto px-4 z-10 text-center space-y-6">\\n        <h1 className="text-4xl md:text-6xl font-serif text-white">{title}</h1>\\n        {description && (\\n          <p className="text-xl text-brand-ivory/80 max-w-2xl mx-auto font-sans">\\n            {description}\\n          </p>\\n        )}\\n      </div>\\n    </section>\\n  )\\n}\\n''',
}

for path, content in components.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)

